 23→function resolvePluginConfig(pluginName: string, configManager: unknown): Record<string, unknown> {
 24→  try {
 25→    const allConfig = (configManager as any)?.get?.() ?? {}
 26→    // Try new format: plugins.builtin['@openacp/speech'].config
 27→    const pluginEntry = allConfig.plugins?.builtin?.[pluginName]
 28→    if (pluginEntry?.config && Object.keys(pluginEntry.config).length > 0) {
 29→      return pluginEntry.config
 30→    }
 31→    // Fallback to legacy config sections
 32→    const legacyMap: Record<string, string> = {
 33→      '@openacp/security': 'security',
 34→      '@openacp/speech': 'speech',
 35→      '@openacp/tunnel': 'tunnel',
 36→      '@openacp/usage': 'usage',
 37→      '@openacp/file-service': 'files',
 38→      '@openacp/api-server': 'api',
 39→      '@openacp/telegram': 'channels.telegram',
 40→      '@openacp/discord': 'channels.discord',
 41→      '@openacp/plugin-discord': 'channels.discord',
 42→      '@openacp/slack': 'channels.slack',
 43→    }
 44→    const legacyKey = legacyMap[pluginName]
 45→    if (legacyKey) {
 46→      const parts = legacyKey.split('.')
 47→      let obj: any = allConfig
 48→      for (const p of parts) obj = obj?.[p]
 49→      if (obj && typeof obj === 'object') return { ...obj }
 50→    }
 51→  } catch {
 52→    // Gracefully degrade — return empty config
 53→  }
 54→  return {}
 55→}
