 57→export interface LifecycleManagerOpts {
 58→  serviceRegistry?: ServiceRegistry
 59→  middlewareChain?: MiddlewareChain
 60→  errorTracker?: ErrorTracker
 61→  eventBus?: EventBus & {
 62→    on(event: string, handler: (...args: unknown[]) => void): void
 63→    off(event: string, handler: (...args: unknown[]) => void): void
 64→    emit(event: string, payload: unknown): void
 65→  }
 66→  storagePath?: string
 67→  sessions?: unknown
 68→  config?: unknown
 69→  core?: unknown
 70→  log?: Logger
 71→  settingsManager?: SettingsManager
 72→  pluginRegistry?: PluginRegistry
 73→}
 74→
 75→export class LifecycleManager {
 76→  readonly serviceRegistry: ServiceRegistry
 77→  readonly middlewareChain: MiddlewareChain
 78→  readonly errorTracker: ErrorTracker
 79→
 80→  private eventBus: LifecycleManagerOpts['eventBus']
 81→  private storagePath: string
 82→  private sessions: unknown
 83→  private config: unknown
 84→  private core: unknown
 85→  private log: Logger | undefined
 86→  private settingsManager: SettingsManager | undefined
 87→  private pluginRegistry: PluginRegistry | undefined
 88→
 89→  private contexts = new Map<string, ReturnType<typeof createPluginContext>>()
 90→  private loadOrder: OpenACPPlugin[] = []
 91→  private _loaded = new Set<string>()
 92→  private _failed = new Set<string>()
 93→
 94→  get loadedPlugins(): string[] {
 95→    return [...this._loaded]
 96→  }
 97→
 98→  get failedPlugins(): string[] {
 99→    return [...this._failed]
100→  }
101→
102→  constructor(opts?: LifecycleManagerOpts) {
103→    this.serviceRegistry = opts?.serviceRegistry ?? new ServiceRegistry()
104→    this.middlewareChain = opts?.middlewareChain ?? new MiddlewareChain()
105→    this.errorTracker = opts?.errorTracker ?? new ErrorTracker()
106→    this.eventBus = opts?.eventBus ?? {
107→      on() {},
108→      off() {},
109→      emit() {},
110→    }
111→    this.storagePath = opts?.storagePath ?? '/tmp/openacp-plugins'
112→    this.sessions = opts?.sessions ?? {}
113→    this.config = opts?.config ?? {}
114→    this.core = opts?.core
115→    this.log = opts?.log
116→    this.settingsManager = opts?.settingsManager
117→    this.pluginRegistry = opts?.pluginRegistry
118→  }
119→
120→  private getPluginLogger(pluginName: string): Logger {
121→    if (this.log && typeof (this.log as any).child === 'function') {
122→      return (this.log as any).child({ plugin: pluginName })
123→    }
124→    return this.log ?? { trace() {}, debug() {}, info() {}, warn() {}, error() {}, fatal() {}, child() { return this } } as Logger
125→  }
126→
127→  async boot(plugins: OpenACPPlugin[]): Promise<void> {
128→    // Resolve load order via topological sort.
129→    // resolveLoadOrder will skip plugins whose dependencies are missing entirely
130→    // (not present in the input list). But we also need to handle runtime setup failures.
131→    // Include already-loaded plugins so dependency checks pass for late-booted plugins
132→    // (e.g., dev plugins booted after core plugins).
133→    const newNames = new Set(plugins.map(p => p.name))
134→    const allForResolution = [...this.loadOrder.filter(p => !newNames.has(p.name)), ...plugins]
135→
136→    let sorted: OpenACPPlugin[]
137→    try {
138→      sorted = resolveLoadOrder(allForResolution)
139→    } catch (err) {
140→      // Circular dependency or other fatal error in resolution
141→      // Mark all as failed
142→      for (const p of plugins) {
143→        this._failed.add(p.name)
144→      }
145→      return
146→    }
147→
148→    // Only boot new plugins (already-loaded ones were included just for dependency resolution)
149→    sorted = sorted.filter(p => newNames.has(p.name))
150→
151→    // Append to existing loadOrder (don't overwrite — hot-reload boots single plugins)
152→    for (const p of sorted) {
153→      if (!this.loadOrder.some(existing => existing.name === p.name)) {
154→        this.loadOrder.push(p)
155→      } else {
156→        // Replace in-place (hot-reload case: plugin was unloaded then re-booted)
157→        const idx = this.loadOrder.findIndex(existing => existing.name === p.name)
158→        this.loadOrder[idx] = p
159→      }
160→    }
161→
162→    for (const plugin of sorted) {
163→      // Check if any required dependency failed at runtime
164→      if (plugin.pluginDependencies) {
165→        const depFailed = Object.keys(plugin.pluginDependencies).some(
166→          (dep) => this._failed.has(dep),
167→        )
168→        if (depFailed) {
169→          this._failed.add(plugin.name)
170→          continue
171→        }
172→      }
173→
174→      // Check if disabled in registry
175→      const registryEntry = this.pluginRegistry?.get(plugin.name)
176→      if (registryEntry && registryEntry.enabled === false) {
177→        this.eventBus?.emit('plugin:disabled', { name: plugin.name })
178→        continue
179→      }
180→
181→      // Check version mismatch → migrate
182→      if (registryEntry && plugin.migrate && registryEntry.version !== plugin.version && this.settingsManager) {
183→        try {
184→          const oldSettings = await this.settingsManager.loadSettings(plugin.name)
185→          const pluginLog = this.getPluginLogger(plugin.name)
186→          const migrateCtx: MigrateContext = {
187→            pluginName: plugin.name,
188→            settings: this.settingsManager.createAPI(plugin.name),
189→            log: pluginLog,
190→          }
191→          const newSettings = await plugin.migrate(migrateCtx, oldSettings, registryEntry.version)
192→          if (newSettings && typeof newSettings === 'object') {
193→            await migrateCtx.settings.setAll(newSettings as Record<string, unknown>)
194→          }
195→          this.pluginRegistry!.updateVersion(plugin.name, plugin.version)
196→          await this.pluginRegistry!.save()
197→        } catch (err) {
198→          this.getPluginLogger(plugin.name).warn(`Migration failed, continuing with old settings: ${err}`)
199→        }
200→      }
201→
202→      // Resolve config: prefer settings.json, fallback to legacy
203→      let pluginConfig: Record<string, unknown>
204→      if (this.settingsManager) {
205→        pluginConfig = await this.settingsManager.loadSettings(plugin.name)
206→        if (Object.keys(pluginConfig).length === 0) {
207→          pluginConfig = resolvePluginConfig(plugin.name, this.config)
208→        }
209→      } else {
210→        pluginConfig = resolvePluginConfig(plugin.name, this.config)
211→      }
212→
213→      // Create context for this plugin
214→      const ctx = createPluginContext({
215→        pluginName: plugin.name,
216→        pluginConfig,
217→        permissions: plugin.permissions ?? [],
218→        serviceRegistry: this.serviceRegistry,
219→        middlewareChain: this.middlewareChain,
220→        errorTracker: this.errorTracker,
221→        eventBus: this.eventBus!,
222→        storagePath: `${this.storagePath}/${plugin.name}`,
223→        sessions: this.sessions,
224→        config: this.config,
225→        core: this.core,
226→        log: this.log,
227→      })
228→
229→      try {
230→        await withTimeout(plugin.setup(ctx), SETUP_TIMEOUT_MS, `${plugin.name}.setup()`)
231→        this.contexts.set(plugin.name, ctx)
232→        this._loaded.add(plugin.name)
233→        this.eventBus?.emit('plugin:loaded', { name: plugin.name, version: plugin.version })
234→      } catch (err) {
235→        this._failed.add(plugin.name)
236→        ctx.cleanup()
237→        this.getPluginLogger(plugin.name).error(`setup() failed: ${err}`)
238→        this.eventBus?.emit('plugin:failed', { name: plugin.name, error: String(err) })
239→      }
240→    }
241→  }
242→
243→  async unloadPlugin(name: string): Promise<void> {
244→    if (!this._loaded.has(name)) return
245→
246→    const plugin = this.loadOrder.find(p => p.name === name)
247→
248→    if (plugin?.teardown) {
249→      try {
250→        await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${name}.teardown()`)
251→      } catch {
252→        // Swallow teardown errors
253→      }
254→    }
255→
256→    const ctx = this.contexts.get(name)
257→    if (ctx) {
258→      ctx.cleanup()
259→      this.contexts.delete(name)
260→    }
261→
262→    this._loaded.delete(name)
263→    this._failed.delete(name)
264→    this.loadOrder = this.loadOrder.filter(p => p.name !== name)
265→
266→    this.eventBus?.emit('plugin:unloaded', { name })
267→  }
268→
269→  async shutdown(): Promise<void> {
270→    // Teardown in reverse load order
271→    const reversed = [...this.loadOrder].reverse()
272→
273→    for (const plugin of reversed) {
274→      if (!this._loaded.has(plugin.name)) continue
275→
276→      if (plugin.teardown) {
277→        try {
278→          await withTimeout(plugin.teardown(), TEARDOWN_TIMEOUT_MS, `${plugin.name}.teardown()`)
279→        } catch {
280→          // Swallow teardown errors — graceful shutdown
281→        }
282→      }
283→
284→      // Clean up the context
285→      const ctx = this.contexts.get(plugin.name)
286→      if (ctx) {
287→        ctx.cleanup()
288→        this.contexts.delete(plugin.name)
289→      }
290→
291→      this.eventBus?.emit('plugin:unloaded', { name: plugin.name })
292→    }
293→
294→    this._loaded.clear()
295→    this.loadOrder = []
296→  }
297→}
