  1→import * as os from "node:os";
  2→import * as path from "node:path";
  3→import * as clack from "@clack/prompts";
  4→import type { Config } from "../config/config.js";
  5→import type { ConfiguredChannelAction, ChannelId, ChannelStatus } from "./types.js";
  6→import { CHANNEL_META } from "./types.js";
  7→import { guardCancel, ok, c } from "./helpers.js";
  8→
  9→export function getChannelStatuses(config: Config): ChannelStatus[] {
 10→  const statuses: ChannelStatus[] = [];
 11→
 12→  for (const [id, meta] of Object.entries(CHANNEL_META) as [ChannelId, typeof CHANNEL_META[ChannelId]][]) {
 13→    const ch = config.channels[id] as Record<string, unknown> | undefined;
 14→    const enabled = ch?.enabled === true;
 15→    const configured = !!ch && Object.keys(ch).length > 1;
 16→
 17→    let hint: string | undefined;
 18→    if (id === "telegram" && ch?.botToken && typeof ch.botToken === "string" && ch.botToken !== "YOUR_BOT_TOKEN_HERE") {
 19→      hint = `Chat ID: ${ch.chatId}`;
 20→    }
 21→    if (id === "discord" && ch?.guildId) {
 22→      hint = `Guild: ${ch.guildId}`;
 23→    }
 24→
 25→    statuses.push({ id, label: meta.label, configured, enabled, hint });
 26→  }
 27→
 28→  return statuses;
 29→}
 30→
 31→export function noteChannelStatus(config: Config): void {
 32→  const statuses = getChannelStatuses(config);
 33→  const lines = statuses.map((s) => {
 34→    const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
 35→    const hintStr = s.hint ? ` — ${s.hint}` : "";
 36→    return `  ${s.label}: ${status}${hintStr}`;
 37→  });
 38→
 39→  console.log("");
 40→  console.log(`${c.bold}  Channel status${c.reset}`);
 41→  for (const line of lines) console.log(line);
 42→  console.log("");
 43→}
