 45→async function promptConfiguredAction(label: string): Promise<ConfiguredChannelAction> {
 46→  return guardCancel(
 47→    await clack.select({
 48→      message: `${label} already configured. What do you want to do?`,
 49→      options: [
 50→        { value: "modify" as const, label: "Modify settings" },
 51→        { value: "disable" as const, label: "Disable bot" },
 52→        { value: "delete" as const, label: "Delete config" },
 53→        { value: "skip" as const, label: "Skip (leave as-is)" },
 54→      ],
 55→      initialValue: "modify" as const,
 56→    }),
 57→  );
 58→}
 59→
 60→async function configureViaPlugin(channelId: ChannelId): Promise<void> {
 61→  const pluginImports: Record<ChannelId, () => Promise<any>> = {
 62→    telegram: () => import('../../plugins/telegram/index.js'),
 63→    discord: async () => {
 64→      const pkg = '@openacp/plugin-discord';
 65→      try {
 66→        return await import(/* webpackIgnore: true */ pkg);
 67→      } catch {
 68→        throw new Error(
 69→          `${pkg} is not installed. Run: openacp plugin add ${pkg}`,
 70→        );
 71→      }
 72→    },
 73→  };
 74→
 75→  const importer = pluginImports[channelId];
 76→  if (!importer) return;
 77→
 78→  const { SettingsManager } = await import('../plugin/settings-manager.js');
 79→  const { createInstallContext } = await import('../plugin/install-context.js');
 80→  const basePath = path.join(os.homedir(), '.openacp', 'plugins');
 81→  const settingsManager = new SettingsManager(basePath);
 82→
 83→  const pluginModule = await importer();
 84→  const plugin = pluginModule.default;
 85→
 86→  if (plugin?.configure) {
 87→    const ctx = createInstallContext({
 88→      pluginName: plugin.name,
 89→      settingsManager,
 90→      basePath,
 91→    });
 92→    await plugin.configure(ctx);
 93→  }
 94→}
