 96→export async function configureChannels(config: Config): Promise<{ config: Config; changed: boolean }> {
 97→  const next = structuredClone(config);
 98→  let changed = false;
 99→
100→  noteChannelStatus(next);
101→
102→  while (true) {
103→    const statuses = getChannelStatuses(next);
104→    const options = statuses.map((s) => {
105→      const status = s.enabled ? "enabled" : s.configured ? "disabled" : "not configured";
106→      return {
107→        value: s.id,
108→        label: `${s.label} (${CHANNEL_META[s.id].method})`,
109→        hint: status + (s.hint ? ` · ${s.hint}` : ""),
110→      };
111→    });
112→
113→    const choice = guardCancel(
114→      await clack.select({
115→        message: "Select a channel",
116→        options: [
117→          ...options,
118→          { value: "__done__" as const, label: "Finished" },
119→        ],
120→      }),
121→    );
122→
123→    if (choice === "__done__") break;
124→
125→    const channelId = choice as ChannelId;
126→    const meta = CHANNEL_META[channelId];
127→    const existing = next.channels[channelId] as Record<string, unknown> | undefined;
128→    const isConfigured = !!existing && Object.keys(existing).length > 1;
129→
130→    if (isConfigured) {
131→      const action = await promptConfiguredAction(meta.label);
132→
133→      if (action === "skip") continue;
134→      if (action === "disable") {
135→        (next.channels[channelId] as Record<string, unknown>).enabled = false;
136→        changed = true;
137→        console.log(ok(`${meta.label} disabled`));
138→        continue;
139→      }
140→      if (action === "delete") {
141→        const confirmed = guardCancel(
142→          await clack.confirm({
143→            message: `Delete ${meta.label} config? This cannot be undone.`,
144→            initialValue: false,
145→          }),
146→        );
147→        if (confirmed) {
148→          delete next.channels[channelId];
149→          changed = true;
150→          console.log(ok(`${meta.label} config deleted`));
151→        }
152→        continue;
153→      }
154→      // action === "modify" — fall through to plugin configure
155→    }
156→
157→    // Run channel configuration via plugin configure()
158→    await configureViaPlugin(channelId);
159→    changed = true;
160→  }
161→
162→  return { config: next, changed };
163→}
