 17→// ─── First-run setup ───
 18→
 19→export async function runSetup(
 20→  configManager: ConfigManager,
 21→  opts?: { skipRunMode?: boolean; settingsManager?: SettingsManager; pluginRegistry?: PluginRegistry },
 22→): Promise<boolean> {
 23→  await printStartBanner();
 24→  clack.intro("Let's set up OpenACP");
 25→
 26→  const { settingsManager, pluginRegistry } = opts ?? {};
 27→
 28→  try {
 29→    if (!settingsManager || !pluginRegistry) {
 30→      console.log(fail('Plugin system not initialized. Cannot set up channels.'));
 31→      return false;
 32→    }
 33→
 34→    // Ask user which channels to set up
 35→    const channelChoices = guardCancel(
 36→      await clack.multiselect({
 37→        message: 'Which channels do you want to set up?',
 38→        options: [
 39→          { value: 'telegram' as const, label: 'Telegram', hint: 'built-in' },
 40→          { value: 'discord' as const, label: 'Discord', hint: 'will install @openacp/plugin-discord' },
 41→        ],
 42→        required: true,
 43→        initialValues: ['telegram' as const],
 44→      }),
 45→    ) as ChannelId[];
 46→
 47→    // Calculate total steps dynamically: channel(s) + workspace + run mode
 48→    const channelSteps = channelChoices.length;
 49→    const runModeSteps = opts?.skipRunMode ? 0 : 1;
 50→    const totalSteps = channelSteps + 1 + runModeSteps; // + workspace + optional run mode
 51→
 52→    let currentStep = 0;
 53→
 54→    const { createInstallContext } = await import('../plugin/install-context.js');
 55→
 56→    for (const channelId of channelChoices) {
 57→      currentStep++;
 58→
 59→      if (channelId === 'telegram') {
 60→        const telegramPlugin = (await import('../../plugins/telegram/index.js')).default;
 61→        const ctx = createInstallContext({
 62→          pluginName: telegramPlugin.name,
 63→          settingsManager,
 64→          basePath: settingsManager.getBasePath(),
 65→        });
 66→        await telegramPlugin.install!(ctx);
 67→        pluginRegistry.register(telegramPlugin.name, {
 68→          version: telegramPlugin.version,
 69→          source: 'builtin',
 70→          enabled: true,
 71→          settingsPath: settingsManager.getSettingsPath(telegramPlugin.name),
 72→          description: telegramPlugin.description,
 73→        });
 74→      }
 75→
 76→      if (channelId === 'discord') {
 77→        await installAndSetupDiscord(settingsManager, pluginRegistry);
 78→      }
 79→    }
 80→
 81→    const { defaultAgent } = await setupAgents();
 82→
 83→    // Offer Claude CLI integration
 84→    await setupIntegrations();
 85→
 86→    currentStep++;
 87→    const workspace = await setupWorkspace({ stepNum: currentStep, totalSteps });
 88→
 89→    let runMode: 'foreground' | 'daemon' = 'foreground';
 90→    let autoStart = false;
 91→    if (!opts?.skipRunMode) {
 92→      currentStep++;
 93→      const result = await setupRunMode({ stepNum: currentStep, totalSteps });
 94→      runMode = result.runMode;
 95→      autoStart = result.autoStart;
 96→    }
 97→
 98→    const security = {
 99→      allowedUserIds: [] as string[],
100→      maxConcurrentSessions: 20,
101→      sessionTimeoutMinutes: 60,
102→    };
103→
104→    const config: Config = {
105→      channels: {},
106→      agents: {},
107→      defaultAgent,
108→      workspace,
109→      security,
110→      logging: {
111→        level: "info",
112→        logDir: "~/.openacp/logs",
113→        maxFileSize: "10m",
114→        maxFiles: 7,
115→        sessionLogRetentionDays: 30,
116→      },
117→      runMode,
118→      autoStart,
119→      api: {
120→        port: 21420,
121→        host: '127.0.0.1',
122→      },
123→      sessionStore: { ttlDays: 30 },
124→      tunnel: {
125→        enabled: true,
126→        port: 3100,
127→        provider: "cloudflare",
128→        options: {},
129→        maxUserTunnels: 5,
130→        storeTtlMinutes: 60,
131→        auth: { enabled: false },
132→      },
133→      usage: {
134→        enabled: true,
135→        warningThreshold: 0.8,
136→        currency: "USD",
137→        retentionDays: 90,
138→      },
139→      integrations: {},
140→      speech: {
141→        stt: { provider: null, providers: {} },
142→        tts: { provider: null, providers: {} },
143→      },
144→    };
145→
146→    try {
147→      await configManager.writeNew(config);
148→    } catch (writeErr) {
149→      console.log(
150→        fail(`Could not save config: ${(writeErr as Error).message}`),
151→      );
152→      return false;
153→    }
154→
155→    // Auto-register remaining built-in plugins in the registry
156→    if (settingsManager && pluginRegistry) {
157→      await registerBuiltinPlugins(settingsManager, pluginRegistry);
158→      await pluginRegistry.save();
