161→    clack.outro(`Config saved to ${configManager.getConfigPath()}`);
162→
163→    if (!opts?.skipRunMode) {
164→      console.log(ok("Starting OpenACP..."));
165→      console.log("");
166→    }
167→
168→    return true;
