178→/**
179→ * Install @openacp/plugin-discord from npm if needed, then run its install() hook.
180→ */
181→async function installAndSetupDiscord(
182→  settingsManager: SettingsManager,
183→  pluginRegistry: PluginRegistry,
184→): Promise<void> {
185→  const packageName = '@openacp/plugin-discord';
186→
187→  // Try to import first — if not installed, install it
188→  let discordPlugin: any;
189→  try {
190→    discordPlugin = (await import(packageName)).default;
191→  } catch {
192→    const spinner = clack.spinner();
193→    spinner.start(`Installing ${packageName}...`);
194→    try {
195→      const pluginsDir = path.join(settingsManager.getBasePath(), 'plugins');
196→      execSync(`npm install ${packageName}`, {
197→        cwd: pluginsDir,
198→        stdio: 'pipe',
199→      });
200→      discordPlugin = (await import(packageName)).default;
201→      spinner.stop(ok(`${packageName} installed`));
202→    } catch (installErr) {
203→      spinner.stop(fail(`Failed to install ${packageName}: ${(installErr as Error).message}`));
204→      console.log(fail('You can install it later with: openacp plugin add @openacp/plugin-discord'));
205→      return;
206→    }
207→  }
208→
209→  const { createInstallContext } = await import('../plugin/install-context.js');
210→  const ctx = createInstallContext({
211→    pluginName: discordPlugin.name,
212→    settingsManager,
213→    basePath: settingsManager.getBasePath(),
214→  });
215→
216→  if (discordPlugin.install) {
217→    await discordPlugin.install(ctx);
218→  }
219→
220→  pluginRegistry.register(discordPlugin.name, {
221→    version: discordPlugin.version,
222→    source: 'npm',
223→    enabled: true,
224→    settingsPath: settingsManager.getSettingsPath(discordPlugin.name),
225→    description: discordPlugin.description,
226→  });
227→}
