235→  pluginRegistry: PluginRegistry,
236→): Promise<void> {
237→  const builtinPlugins = [
238→    { name: '@openacp/security', version: '1.0.0', description: 'User access control and session limits' },
239→    { name: '@openacp/file-service', version: '1.0.0', description: 'File storage and management' },
240→    { name: '@openacp/context', version: '1.0.0', description: 'Conversation context management' },
