242→    { name: '@openacp/speech', version: '1.0.0', description: 'Text-to-speech and speech-to-text' },
243→    { name: '@openacp/notifications', version: '1.0.0', description: 'Cross-session notification routing' },
244→    { name: '@openacp/tunnel', version: '1.0.0', description: 'Expose local services via tunnel' },
245→    { name: '@openacp/api-server', version: '1.0.0', description: 'REST API + SSE streaming server' },
