266→  return guardCancel(
267→    await clack.select({
268→      message: "Select sections to configure",
269→      options: [
270→        ...ONBOARD_SECTION_OPTIONS,
271→        {
272→          value: "__continue" as const,
273→          label: "Continue",
274→          hint: hasSelection ? "Done" : "Skip for now",
275→        },
276→      ],
277→      initialValue: ONBOARD_SECTION_OPTIONS[0].value,
278→    }),
