282→export async function runReconfigure(configManager: ConfigManager): Promise<void> {
283→  await printStartBanner();
284→  clack.intro("OpenACP — Reconfigure");
285→
286→  try {
287→    await configManager.load();
288→    let config = configManager.get();
289→
290→    // Show current config summary
291→    clack.note(summarizeConfig(config), "Current configuration");
292→
293→    let ranSection = false;
294→
295→    while (true) {
296→      const choice = await selectSection(ranSection);
297→      if (choice === "__continue") break;
298→      ranSection = true;
299→
300→      if (choice === "channels") {
301→        const result = await configureChannels(config);
302→        if (result.changed) {
303→          // IMPORTANT: Use writeNew() instead of save() because save() uses deepMerge
304→          // which cannot delete keys. Channel deletion (delete next.channels.telegram)
305→          // would be silently ignored by deepMerge. writeNew() overwrites the full config.
306→          config = { ...config, channels: result.config.channels };
307→          await configManager.writeNew(config);
308→        }
309→      }
310→
311→      if (choice === "agents") {
312→        const { defaultAgent } = await setupAgents();
313→        await configManager.save({ defaultAgent });
314→        config = configManager.get();
315→      }
316→
317→      if (choice === "workspace") {
318→        const { baseDir } = await setupWorkspace({
319→          existing: config.workspace.baseDir,
320→        });
321→        await configManager.save({ workspace: { baseDir } });
322→        config = configManager.get();
323→      }
324→
325→      if (choice === "runMode") {
326→        const result = await setupRunMode({
327→          existing: { runMode: config.runMode, autoStart: config.autoStart },
328→        });
329→        await configManager.save({
330→          runMode: result.runMode,
331→          autoStart: result.autoStart,
332→        });
333→        config = configManager.get();
334→      }
335→
336→      if (choice === "integrations") {
337→        await setupIntegrations(config);
338→      }
339→    }
340→
341→    if (!ranSection) {
342→      clack.outro("No changes made.");
343→      return;
344→    }
345→
346→    clack.outro(`Config saved to ${configManager.getConfigPath()}`);
347→  } catch (err) {
348→    if ((err as Error).name === "ExitPromptError") {
349→      clack.cancel("Setup cancelled.");
350→      return;
351→    }
352→    throw err;
353→  }
354→}
